-- m39: Mini-quests semanais (NPC desafiante escondido nos mapas). Gerado por script a partir dos mapas.

create table if not exists public.miniquests_catalogo (
  id text primary key references public.treinadores (id) on delete cascade,
  mapa_id text not null references public.mapas (id) on delete cascade,
  nome text not null,
  dica text not null default '',
  recompensa jsonb not null default '{}'::jsonb,
  ativa boolean not null default true
);
create table if not exists public.miniquests_semana (
  semana date not null,
  miniquest text not null references public.miniquests_catalogo (id) on delete cascade,
  primary key (semana, miniquest)
);
create table if not exists public.miniquests_jogador (
  jogador uuid not null references public.jogadores (id) on delete cascade,
  semana date not null,
  miniquest text not null references public.miniquests_catalogo (id) on delete cascade,
  concluida_em timestamptz not null default now(),
  primary key (jogador, semana, miniquest)
);
alter table public.miniquests_catalogo enable row level security;
alter table public.miniquests_semana enable row level security;
alter table public.miniquests_jogador enable row level security;
drop policy if exists mqj_dono on public.miniquests_jogador;
create policy mqj_dono on public.miniquests_jogador for select to authenticated using (jogador = auth.uid() or public.eh_mestre());
grant select on public.miniquests_jogador to authenticated;
insert into public.config (chave, valor) values ('miniquests_por_semana', '12'::jsonb) on conflict (chave) do nothing;

insert into public.treinadores (id, mapa_id, x, y, direcao, visao, nome, classe, aparencia, recompensa, falas, equipe, escala, arco) select 'mq_porto', 'porto', 21, 7, 'baixo', 1, 'Rafa', 'Veterano', 0, 0, '{"antes": "Ouvi dizer que você é bom. Prove!", "derrota": "Você venceu! Fico com vontade de treinar mais."}'::jsonb, '[]'::jsonb, '{"bonus": 2, "time": 4, "pool": [{"e": 74, "de": 1, "ate": 24, "linha": 74}, {"e": 75, "de": 25, "ate": 38, "linha": 74}, {"e": 76, "de": 39, "ate": 100, "linha": 74}, {"e": 95, "de": 1, "ate": 100, "linha": 95}, {"e": 111, "de": 1, "ate": 41, "linha": 111}, {"e": 112, "de": 42, "ate": 100, "linha": 111}, {"e": 27, "de": 1, "ate": 21, "linha": 27}, {"e": 28, "de": 22, "ate": 100, "linha": 27}, {"e": 104, "de": 1, "ate": 27, "linha": 104}, {"e": 105, "de": 28, "ate": 100, "linha": 104}, {"e": 50, "de": 1, "ate": 25, "linha": 50}, {"e": 51, "de": 26, "ate": 100, "linha": 50}, {"e": 140, "de": 1, "ate": 39, "linha": 140}, {"e": 141, "de": 40, "ate": 100, "linha": 140}, {"e": 138, "de": 1, "ate": 39, "linha": 138}, {"e": 139, "de": 40, "ate": 100, "linha": 138}], "piso": 18, "var": 0}'::jsonb, 1 where exists (select 1 from public.mapas where id = 'porto') on conflict (id) do update set x = excluded.x, y = excluded.y, escala = excluded.escala, falas = excluded.falas;
