-- ---------- sorteio da semana ----------
create or replace function public._miniquests_semana() returns date language plpgsql security definer set search_path = public as $$
declare s date := public._semana_inicio(public._dia_jogo()); n int := public._cfg_int('miniquests_por_semana', 12);
begin
  if exists (select 1 from public.miniquests_semana where semana = s) then return s; end if;
  perform pg_advisory_xact_lock(7703);
  if not exists (select 1 from public.miniquests_semana where semana = s) then
    insert into public.miniquests_semana (semana, miniquest)
    select s, c.id from public.miniquests_catalogo c where c.ativa order by md5(c.id || s::text) limit greatest(n, 0)
    on conflict do nothing;
    delete from public.miniquests_semana where semana < s - 28;
  end if;
  return s;
end $$;
revoke all on function public._miniquests_semana() from public, anon, authenticated;

create or replace function public._miniquest_disponivel(p_j uuid, p_id text) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.miniquests_semana ms join public.miniquests_catalogo c on c.id = ms.miniquest
                  where ms.semana = public._semana_inicio(public._dia_jogo()) and ms.miniquest = p_id and c.ativa)
     and not exists (select 1 from public.miniquests_jogador mj where mj.jogador = p_j and mj.semana = public._semana_inicio(public._dia_jogo()) and mj.miniquest = p_id) $$;
revoke all on function public._miniquest_disponivel(uuid, text) from public, anon, authenticated;

-- NPCs desafiantes ativos num mapa (formato de treinador, para o jogo desenhar)
create or replace function public.miniquests_mapa(p_mapa text) returns jsonb language plpgsql security definer set search_path = public as $$
declare s date;
begin
  if auth.uid() is null or not public._modulo('miniquests') then return '[]'::jsonb; end if;
  s := public._miniquests_semana();
  return coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'mapa_id', t.mapa_id, 'x', t.x, 'y', t.y, 'direcao', t.direcao, 'visao', 0, 'nome', t.nome, 'classe', t.classe,
                      'aparencia', t.aparencia, 'recompensa', 0, 'falas', t.falas, 'lider', false, 'miniquest', true))
                     from public.miniquests_semana ms join public.treinadores t on t.id = ms.miniquest join public.miniquests_catalogo c on c.id = ms.miniquest
                    where ms.semana = s and t.mapa_id = p_mapa and c.ativa and public._miniquest_disponivel(auth.uid(), t.id)), '[]'::jsonb);
end $$;

-- visão geral da semana (tela de Mini-quests e Mapa Mundi)
create or replace function public.miniquests_listar() returns jsonb language plpgsql security definer set search_path = public as $$
declare s date;
begin
  if auth.uid() is null or not public._modulo('miniquests') then return jsonb_build_object('ativo', false); end if;
  s := public._miniquests_semana();
  return jsonb_build_object('ativo', true, 'semana', s, 'termina_em', (s + 7),
    'lista', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'mapa_id', c.mapa_id, 'mapa', (select m.nome from public.mapas m where m.id = c.mapa_id), 'nome', c.nome, 'dica', c.dica,
                'recompensa', c.recompensa, 'feita', exists (select 1 from public.miniquests_jogador mj where mj.jogador = auth.uid() and mj.semana = s and mj.miniquest = c.id)) order by c.nome)
              from public.miniquests_semana ms join public.miniquests_catalogo c on c.id = ms.miniquest where ms.semana = s and c.ativa), '[]'::jsonb));
end $$;

-- vitória sobre o desafiante: entrega a recompensa uma vez por semana
create or replace function public._tg_batalha_miniquest() returns trigger language plpgsql security definer set search_path = public as $$
declare c public.miniquests_catalogo; s date := public._semana_inicio(public._dia_jogo());
begin
  if old.estado = 'ativa' and new.estado = 'vitoria' and new.tipo = 'treinador' and new.treinador like 'mq\_%' then
    begin
      select * into c from public.miniquests_catalogo where id = new.treinador and ativa;
      if found and exists (select 1 from public.miniquests_semana where semana = s and miniquest = c.id)
         and not exists (select 1 from public.miniquests_jogador where jogador = new.jogador and semana = s and miniquest = c.id) then
        insert into public.miniquests_jogador (jogador, semana, miniquest) values (new.jogador, s, c.id);
        perform public._conceder(new.jogador, c.recompensa);
        perform public._atividade(new.jogador, 'miniquest', c.id);
      end if;
    exception when others then
      raise warning 'tg_batalha_miniquest falhou: %', sqlerrm;
    end;
  end if;
  return new;
end $$;
drop trigger if exists tg_batalha_miniquest on public.batalhas;
create trigger tg_batalha_miniquest after update of estado on public.batalhas for each row execute function public._tg_batalha_miniquest();

-- ---------- Mestre ----------
create or replace function public.mestre_miniquests_obter() returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not public.eh_mestre() then raise exception 'Só o Mestre.'; end if;
  return jsonb_build_object('por_semana', public._cfg_int('miniquests_por_semana', 12),
    'lista', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'mapa_id', c.mapa_id, 'nome', c.nome, 'dica', c.dica, 'recompensa', c.recompensa, 'ativa', c.ativa,
        'sorteada', exists (select 1 from public.miniquests_semana ms where ms.semana = public._semana_inicio(public._dia_jogo()) and ms.miniquest = c.id)) order by c.mapa_id)
        from public.miniquests_catalogo c), '[]'::jsonb));
end $$;

create or replace function public.mestre_miniquests_salvar(p jsonb) returns void language plpgsql security definer set search_path = public as $$
declare q jsonb;
begin
  if not public.eh_mestre() then raise exception 'Só o Mestre.'; end if;
  if p ? 'por_semana' then
    if (p ->> 'por_semana')::int not between 0 and 100 then raise exception 'Quantidade por semana inválida.'; end if;
    insert into public.config (chave, valor) values ('miniquests_por_semana', to_jsonb((p ->> 'por_semana')::int)) on conflict (chave) do update set valor = excluded.valor;
  end if;
  for q in select * from jsonb_array_elements(coalesce(p -> 'lista', '[]'::jsonb)) loop
    perform public._payload_ok(q -> 'recompensa');
    update public.miniquests_catalogo set nome = coalesce(nullif(q ->> 'nome', ''), nome), dica = coalesce(q ->> 'dica', dica),
      recompensa = coalesce(q -> 'recompensa', recompensa), ativa = coalesce((q ->> 'ativa')::boolean, ativa) where id = q ->> 'id';
  end loop;
  if coalesce((p ->> 'resortear')::boolean, false) then
    delete from public.miniquests_semana where semana = public._semana_inicio(public._dia_jogo());
    perform public._miniquests_semana();
  end if;
end $$;

do $$ declare f text; begin
  foreach f in array array['miniquests_mapa(text)', 'miniquests_listar()', 'mestre_miniquests_obter()', 'mestre_miniquests_salvar(jsonb)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;

-- ---------- desafiar_treinador: NPCs de mini-quest só valem se estiverem ativos e pendentes na semana ----------

create or replace function public.desafiar_treinador(p_treinador text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_j public.jogadores; v_t public.treinadores; v_b public.batalhas; v_ativo uuid; v_falta int; v_rev boolean := false;
  begin
  if auth.uid() is null then raise exception 'Faça login primeiro.'; end if;
  select * into v_j from public.jogadores where id = auth.uid() for update;
  if not found then raise exception 'Crie seu personagem primeiro.'; end if;
  select * into v_b from public.batalhas where jogador = v_j.id and estado = 'ativa';
  if found then return jsonb_build_object('batalha', to_jsonb(v_b) - 'sim' - 'meta'); end if;
  select * into v_t from public.treinadores where id = p_treinador and mapa_id = v_j.mapa_id;
  if not found then raise exception 'Não há esse treinador por aqui.'; end if;
  if v_t.id like 'mq\_%' then
    if not public._modulo('miniquests') or not public._miniquest_disponivel(v_j.id, v_t.id) then
      raise exception '% não está desafiando ninguém agora.', v_t.nome;
    end if;
  elsif exists (select 1 from public.treinadores_vencidos where jogador = v_j.id and treinador = v_t.id) then
    if public._modulo('ranking') and not exists (select 1 from public.treinadores_revanche r where r.jogador = v_j.id and r.treinador = v_t.id and r.dia_jogo >= public._dia_jogo()) then
      v_rev := true;
    elsif public._modulo('ranking') then
      raise exception '% só aceita nova revanche a partir da virada do dia.', v_t.nome;
    else
      raise exception 'Você já derrotou % .', v_t.nome;
    end if;
  end if;
  -- líder (ginásio/Liga): antes é preciso vencer todos os outros treinadores do mesmo local
  if v_t.lider then
    select count(*) into v_falta from public.treinadores o
     where o.mapa_id = v_t.mapa_id and o.id <> v_t.id and not o.lider
       and not exists (select 1 from public.treinadores_vencidos tv where tv.jogador = v_j.id and tv.treinador = o.id);
    if v_falta > 0 then
      raise exception '% só aceita o desafio de quem venceu antes todos os treinadores do ginásio (faltam %).', v_t.nome, v_falta;
    end if;
  end if;
  -- o treinador só desafia quando o jogador puxa conversa: precisa estar num tile ao lado dele
  if abs(v_t.x - v_j.x) + abs(v_t.y - v_j.y) <> 1 then raise exception 'Chegue ao lado de % para conversar.', v_t.nome; end if;
  select id into v_ativo from public.pokemons where dono = v_j.id and posicao is not null and hp_atual > 0 order by posicao limit 1;
  if v_ativo is null then
    if exists (select 1 from public.pokemons where dono = v_j.id) then raise exception 'Seus Pokémon estão desmaiados. Cure-os no Centro Pokémon ou em casa.';
    else raise exception 'Você ainda não tem Pokémon. Fale com o Professor Carvalho no laboratório.'; end if;
  end if;
  insert into public.batalhas (jogador, selvagem, ativo, tipo, treinador, adversarios, revanche)
  values (v_j.id, '{}'::jsonb, v_ativo, 'treinador', v_t.id, case when v_t.escala is not null then public._equipe_escalada(v_t, public._nivel_ref(v_j.id)) else public._equipe_treinador(v_t.equipe) end, v_rev) returning * into v_b;
  if v_rev then
    insert into public.treinadores_revanche (jogador, treinador, dia_jogo) values (v_j.id, v_t.id, public._dia_jogo())
    on conflict (jogador, treinador) do update set dia_jogo = excluded.dia_jogo;
  end if;
  return jsonb_build_object('batalha', to_jsonb(v_b) - 'sim' - 'meta', 'treinador', jsonb_build_object('nome', v_t.nome, 'classe', v_t.classe));
end $$;
